import itertools
import json

riders = ["R", "S", "T", "Y"]
bikes = ["F", "G", "H", "J"]

# All bijections rider -> bike for one day.
days = [dict(zip(riders, p)) for p in itertools.permutations(bikes)]

def day_ok(d):
    # Reynaldo cannot test F; Yuki cannot test J (applies on each day).
    return d["R"] != "F" and d["Y"] != "J"

def valid_pair(d1, d2):
    if not (day_ok(d1) and day_ok(d2)):
        return False
    # Each rider tests a different bike on day 2 than on day 1.
    if any(d1[r] == d2[r] for r in riders):
        return False
    # Theresa must be a tester for H (on either day).
    if not (d1["T"] == "H" or d2["T"] == "H"):
        return False
    # Yuki's day-1 bike must be tested by Seamus on day 2.
    if d1["Y"] != d2["S"]:
        return False
    return True

# Antecedent: Theresa tests J on the first day.
solutions = []
for d1 in days:
    if d1["T"] != "J":
        continue
    for d2 in days:
        if valid_pair(d1, d2):
            solutions.append((d1, d2))

options = {
    "A": lambda d1, d2: d2["R"] == "G",
    "B": lambda d1, d2: d1["S"] == "H",
    "C": lambda d1, d2: d2["Y"] == "H",
    "D": lambda d1, d2: "J" in (d1["S"], d2["S"]),
    "E": lambda d1, d2: "G" in (d1["T"], d2["T"]),
}

possible = []
for letter, pred in options.items():
    if any(pred(d1, d2) for d1, d2 in solutions):
        possible.append(letter)

if len(possible) == 1:
    final_answer = possible[0]
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "antecedent": "T on J day 1",
    "num_solutions": len(solutions),
    "options_possible": possible,
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}, separators=(",", ":")))
